import type { UIMessage } from 'ai';

function MessageList({ messages }: { messages: UIMessage[] }) {
  return (
    <>
      {messages.map((m) => (
        <div key={m.id}>
          {m.parts.map((part, i) => {
            if (part.type === 'text') return <span key={i}>{part.text}</span>;
            return null;
          })}
        </div>
      ))}
    </>
  );
}

