// v5 tool part states:
// partial-call  -> input-streaming
// call          -> input-available
// result        -> output-available
// (new)            output-error

switch (part.state) {
  case 'input-streaming':
    return <div>Streaming input...</div>;
  case 'input-available':
    return <div>Executing tool...</div>;
  case 'output-available':
    return <div>{JSON.stringify(part.output)}</div>;
  case 'output-error':
    return <div>Error: {part.errorText}</div>;
}

import { createUIMessageStream, createUIMessageStreamResponse } from 'ai';

export async function POST(req: Request) {
  const stream = createUIMessageStream({
    execute({ writer }) {
      writer.write({ type: 'data-event', id: 'e1', data: 'started' });
      // merge the LLM stream
      writer.merge(streamText({ model, messages: [] }).toUIMessageStream());
    },
  });
  return createUIMessageStreamResponse({ stream });
}
